static AiplVal aipl_rt_parallel_emit_c(AiplVal v_hir, AiplVal v_safeFile) {
  AiplVal funcs = aipl_member_get(v_hir, "functions");
  int64_t total = aipl_member_get(funcs, "len").i;
  int ncpus = (int)aipl_rt_hardware_concurrency().i;
  if (total < 16 || ncpus <= 1) {
    return aipl_fn_emitCFunctionsStride(v_hir, v_safeFile, aipl_int(0), aipl_int(1));
  }
  int workers = (ncpus < (int)total) ? ncpus : (int)total;
  if (workers > 4) workers = 4;
  fflush(stdout); fflush(stderr);
  static int g_emit_seq = 0;
  int seq = __sync_fetch_and_add(&g_emit_seq, 1);
  pid_t parent_pid = getpid();
  pid_t* pids = (pid_t*)malloc(sizeof(pid_t) * (size_t)workers);
  char part_files[64][256];
  for (int w = 0; w < workers; w++) {
    snprintf(part_files[w], sizeof(part_files[w]), "/tmp/aipl_emit_%d_%d_%d.part", (int)parent_pid, seq, w);
    pid_t pid = fork();
    if (pid == 0) {
      AiplVal part = aipl_fn_emitCFunctionsStride(v_hir, v_safeFile, aipl_int(w), aipl_int(workers));
      FILE* fp = fopen(part_files[w], "wb");
      if (fp) {
        if (part.kind == AIPL_STR && part.s) {
          fwrite(part.s, 1, strlen(part.s), fp);
        }
        fclose(fp);
      }
      _exit(0);
    }
    pids[w] = pid;
  }
  int any_failed = 0;
  for (int w = 0; w < workers; w++) {
    int status = 0;
    if (pids[w] > 0) {
      waitpid(pids[w], &status, 0);
      if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        any_failed = 1;
      }
    }
  }
  if (any_failed) {
    free(pids);
    for (int w = 0; w < workers; w++) {
      unlink(part_files[w]);
    }
    return aipl_fn_emitCFunctionsStride(v_hir, v_safeFile, aipl_int(0), aipl_int(1));
  }
  free(pids);
  size_t total_bytes = 0;
  size_t part_sizes[64];
  for (int w = 0; w < workers; w++) {
    struct stat st;
    if (stat(part_files[w], &st) == 0) {
      part_sizes[w] = (size_t)st.st_size;
      total_bytes += (size_t)st.st_size + 1;
    } else {
      part_sizes[w] = 0;
    }
  }
  char* out_buf = (char*)malloc(total_bytes + 1);
  size_t offset = 0;
  for (int w = 0; w < workers; w++) {
    if (part_sizes[w] > 0) {
      FILE* fp = fopen(part_files[w], "rb");
      if (fp) {
        size_t nread = fread(out_buf + offset, 1, part_sizes[w], fp);
        offset += nread;
        fclose(fp);
      }
    }
    unlink(part_files[w]);
    if (offset < total_bytes && (offset == 0 || out_buf[offset - 1] != '\n')) {
      out_buf[offset++] = '\n';
    }
  }
  out_buf[offset] = 0;
  AiplVal res = aipl_str_n(out_buf, (int64_t)offset);
  free(out_buf);
  return res;
}
